<?php $permissions=json_decode($account['permissions']??'[]',true)?:[];$permissionGroups=[];foreach(az_permission_labels() as $key=>$label){$group=match(explode('.',$key)[0]){'finance'=>'Finance','event','participants','payments','tickets','submissions','operations'=>'Event operations','settings','audit'=>'Platform controls',default=>'Publishing'};$permissionGroups[$group][$key]=$label;} ?>
<div class="permission-grid"><?php foreach($permissionGroups as $group=>$items): ?><details class="permission-group studio-disclosure"><summary><?= e($group) ?></summary><div class="disclosure-content"><?php foreach($items as $key=>$label): ?><label class="check-field"><input type="checkbox" name="permissions[]" value="<?= e($key) ?>" <?= in_array($key,$permissions,true)?'checked':'' ?>><?= e($label) ?></label><?php endforeach; ?></div></details><?php endforeach; ?></div>
